/**
 * 天气图标 —— 由 scripts/gen-meteocons-icons.mjs 从 @meteocons/svg-static 生成，不要手改。
 *
 * 用法见 @/utils/weather 的注释。改图标回去跑 `pnpm weather-icons`，这里只保存生成结果。
 *
 * 图标本体来自 Meteocons（https://github.com/basmilius/meteocons），MIT 许可。
 */

/** Meteocons 图标名。取值与 @meteocons/svg-static 的文件名一致 */
export type WeatherIconSlug =
  | 'clear-day'
  | 'clear-night'
  | 'partly-cloudy-day'
  | 'partly-cloudy-night'
  | 'cloudy'
  | 'overcast'
  | 'drizzle'
  | 'rain'
  | 'sleet'
  | 'snow'
  | 'hail'
  | 'thunderstorms'
  | 'thunderstorms-hail'
  | 'mist'
  | 'fog'
  | 'haze'
  | 'dust'
  | 'sun-hot'
  | 'snowflake'
  | 'moon-new'
  | 'moon-waxing-crescent'
  | 'moon-first-quarter'
  | 'moon-waxing-gibbous'
  | 'moon-full'
  | 'moon-waning-gibbous'
  | 'moon-last-quarter'
  | 'moon-waning-crescent';

/**
 * 天气码用的图标名 —— 月相那几枚除外。
 *
 * 月相图标是给月相卡画的，天气码永远不会落到它们身上。
 * 摘成单独一族，别处按图形分派别时就不必再判一次月相。
 */
export type WeatherCodeIconSlug = Exclude<WeatherIconSlug, `moon-${string}`>;

